// A field ramp of `ftle` as a lightness (colour_composition §1.2, §4.1; render::colour::field_ramp): the `lin`
// compaction, polarity high. A blank, unset or invalid sample returns 0: its style is drawn by the ramp's post.
// @name ftle lightness
// @group Brightness
// @about ftle as a lightness; its post draws its styles.
// @maps ftle [lin, polarity high]
// @glyph ramp
// @uniform u_range: vec2<f32> = (0.0, 1.0)
// @control u_range hidden "Measured range"
fn brightness(ctx: Ctx) -> f32 {
    let v = ctx.sample.ftle;
    if (ctx.validity.forbidden || ctx.sample.state == STATE_DECODE_FAILED) { return 0.0; }
    if (ctx.sample.state == STATE_SIM_FAILED || ctx.sample.state > STATE_DECODE_FAILED) { return 0.0; }
    if (!(has_ftle && ctx.sample.ftle_valid && (bitcast<u32>(v) & 0x7f800000u) != 0x7f800000u)) {
        if ((has_ftle && ctx.sample.ftle_valid) && (bitcast<u32>(v) & 0x7f800000u) == 0x7f800000u) { note_non_finite(); }
        return 0.0;
    }
    return range_norm(v, uniforms.u_range.x, uniforms.u_range.y, false, vec2<f32>(0.0, 0.0));
}

// The styles of the field ramp of `ftle` (colour_composition §4.1; render::colour::field_ramp): the background, "not yet"
// and the invalid lane over the combiner's output, #141418 unless INVALID_OVERRIDE is 1; every other colour as it is.
// @name ftle styles
// @group Post
// @about The background, not-yet and invalid styles of the ftle lightness, over the combiner's colour.
// @maps ftle [lin, polarity high]
// @glyph name
// @uniform INVALID_OVERRIDE: u32 = 0 [0, 1]
// @uniform INVALID_COLOUR: vec3<f32> = (1.0, 0.0, 1.0)
// @control INVALID_OVERRIDE toggle "Override the invalid colour" in "Invalid"
// @control INVALID_COLOUR colour "Invalid colour" in "Invalid"
fn post(ctx: Ctx, rgb: vec3<f32>) -> vec3<f32> {
    let v = ctx.sample.ftle;
    if (ctx.validity.forbidden || ctx.sample.state == STATE_DECODE_FAILED) { return canvas_background(); }
    if (ctx.sample.state == STATE_SIM_FAILED || ctx.sample.state > STATE_DECODE_FAILED) { return select(PRESENT_INVALID, uniforms.INVALID_COLOUR, uniforms.INVALID_OVERRIDE != 0u); }
    if (!(has_ftle && ctx.sample.ftle_valid && (bitcast<u32>(v) & 0x7f800000u) != 0x7f800000u)) {
        if ((has_ftle && ctx.sample.ftle_valid) && (bitcast<u32>(v) & 0x7f800000u) == 0x7f800000u) { note_non_finite(); }
        return select(PRESENT_INVALID, uniforms.INVALID_COLOUR, uniforms.INVALID_OVERRIDE != 0u);
    }
    return rgb;
}
